#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <limits.h>

int cmp(const void *x, const void *y) {
    int a = *(const int *)x;
    int b = *(const int *)y;
    return (a > b) - (a < b);
}

int main(void) {
    int n, a[512];
    scanf("%d", &n);
    for (int i = 0; i < n; ++i) {
        scanf("%d", &a[i]);
    }
    qsort(a,n,sizeof *a,cmp);
    int distinct=0,found=0;
    for(int i=n-1;i>=0;i--) {
        if(i==n-1||a[i]!=a[i+1]) distinct++;
        if(distinct==3) {
            printf("%d\n",a[i]);
            found=1;
            break;
        }
    }
    if(!found) puts("NONE");
    return 0;
}

