    for(int i=0;i<m;i++) {
        int u,v,cost;
        scanf("%d%d%d",&u,&v,&cost);
        w[u][v]=cost;
        w[v][u]=cost;
    }
    int d[32],used[32]= {
        0
    }
    ;
    for(int i=0;i<n;i++) d[i]=1000000;
    d[0]=0;
    for(int step=0;step<n;step++) {
        int u=-1;
        for(int i=0;i<n;i++) if(!used[i]&&(u<0||d[i]<d[u])) u=i;
        if(u<0||d[u]==1000000) break;
        used[u]=1;
        for(int v=0;v<n;v++) if(w[u][v]&&d[u]+w[u][v]<d[v]) d[v]=d[u]+w[u][v];
