    int value;
    struct Node *next;
}
Node;
Node *reverse(Node *h) {
    Node *prev=NULL;
    while(h) {
        Node *next=h->next;
        h->next=prev;
        prev=h;
        h=next;
    }
    return prev;
}

int main(void) {
    int n;
    scanf("%d",&n);
    Node *head=NULL, **tail=&head;
