        p->next=NULL;
        *tail=p;
        tail=&p->next;
    }
    head=reverse(head);
    if(!head) puts("EMPTY");
    int first=1;
    for(Node *p=head;p;p=p->next) {
        printf("%s%d",first?"":" ",p->value);
        first=0;
    }
    if(head) puts("");
    while(head) {
        Node *next=head->next;
        free(head);
        head=next;
    }
    return 0;
}

